-- Gerado por `bun run seed` a partir de content/questions/. Não edite à mão.

insert into public.topics (slug, name, sort_order) values
  ('argumentacao', 'Argumentação e silogismos', 2),
  ('associacaoLogica', 'Associação lógica', 4),
  ('fracoes', 'Problemas com frações', 9),
  ('porcentagem', 'Porcentagem', 10),
  ('probabilidade', 'Probabilidade', 11),
  ('proposicoes', 'Proposições e conectivos', 1),
  ('sequenciasFiguras', 'Sequências de figuras', 8),
  ('sequenciasLetras', 'Sequências de letras', 6),
  ('sequenciasNumericas', 'Sequências numéricas', 5),
  ('sequenciasPalavras', 'Palavras e analogias', 7),
  ('verdadeMentira', 'Verdade e mentira', 3)
on conflict (slug) do update set
  name = excluded.name,
  sort_order = excluded.sort_order;

insert into public.questions
  (id, topic_id, statement, premises, prompt, options, correct_index, explanation, difficulty, active)
select v.id, t.id, v.statement, v.premises, v.prompt, v.options, v.correct_index, v.explanation, v.difficulty, true
from (values
  ('arg-01', 'argumentacao', 'Todo A é B. Nenhum B é C.', null::text[], 'Qual conclusão é necessariamente verdadeira?', array['Algum C é B.', 'Todo C é A.', 'Nenhum A é C.', 'Algum A é C.', 'Todo B é A.']::text[], 2, 'Todos os A estão dentro de B, e B não tem nada em comum com C. Logo, nenhum A pode ser C.', 1),
  ('arg-02', 'argumentacao', 'Alguns médicos são músicos. Todos os músicos são criativos.', null::text[], 'Qual conclusão é necessariamente verdadeira?', array['Alguns médicos são criativos.', 'Alguns criativos não são médicos.', 'Todos os médicos são criativos.', 'Nenhum médico é criativo.', 'Todos os criativos são músicos.']::text[], 0, 'Os médicos que são músicos são, por serem músicos, criativos. Então pelo menos alguns médicos são criativos.', 2),
  ('arg-03', 'argumentacao', 'Todos os gatos são mamíferos. Alguns mamíferos voam.', null::text[], 'O que se pode concluir com certeza?', array['Alguns gatos voam.', 'Todos os mamíferos são gatos.', 'Os mamíferos que voam são gatos.', 'Nada se pode concluir sobre gatos voarem.', 'Nenhum gato voa.']::text[], 3, 'Os mamíferos que voam podem ser outros animais (morcegos, por exemplo). As premissas não ligam gatos a voar.', 2),
  ('arg-04', 'argumentacao', 'Se o alarme tocar, Rita acorda. Rita não acordou.', null::text[], 'O que se conclui?', array['Rita acordará depois.', 'Nada se pode concluir.', 'O alarme tocou.', 'O alarme não tocou.', 'O alarme está quebrado.']::text[], 3, 'Se p → q e q é falso, então p é falso (modus tollens). Se o alarme tivesse tocado, Rita teria acordado.', 2),
  ('arg-05', 'argumentacao', 'Se o alarme tocar, Rita acorda. Rita acordou.', null::text[], 'O que se conclui com certeza?', array['O alarme tocará amanhã.', 'Nada se pode concluir sobre o alarme.', 'O alarme não tocou.', 'O alarme tocou.', 'Rita acorda só com o alarme.']::text[], 1, 'Rita pode ter acordado por outro motivo. Concluir que o alarme tocou é um erro comum, chamado afirmação do consequente.', 3),
  ('arg-06', 'argumentacao', 'Nenhum político é honesto. Alguns honestos são advogados.', null::text[], 'Qual conclusão é necessariamente verdadeira?', array['Alguns advogados não são políticos.', 'Alguns políticos são advogados.', 'Todos os advogados são honestos.', 'Nenhum advogado é político.', 'Todos os honestos são advogados.']::text[], 0, 'Os advogados honestos não podem ser políticos (nenhum político é honesto). Então pelo menos alguns advogados não são políticos.', 3),
  ('assoc-01', 'associacaoLogica', 'Ana, Bruno e Carla são, em alguma ordem, médico(a), engenheiro(a) e professor(a).', array['I. Ana não é professora.', 'II. Carla não é engenheira.', 'III. Quem é médico é mais velho que Ana.', 'IV. Bruno não é médico.']::text[], 'Quem é médico(a)?', array['Ana', 'Ana ou Carla', 'Não é possível determinar', 'Bruno', 'Carla']::text[], 4, 'Pela III, Ana não é médica; pela I, também não é professora, então é engenheira. Pela IV, Bruno não é médico, logo é professor. Sobra Carla: médica.', 2),
  ('assoc-02', 'associacaoLogica', 'Lia, Mel e Nina moram em casas de cores diferentes (azul, verde e branca) e cada uma tem um animal diferente (gato, cão e peixe).', array['Lia não mora na casa azul.', 'Quem mora na casa verde tem um gato.', 'Mel tem um peixe.', 'Nina não mora na casa verde.', 'Mel não mora na casa branca.']::text[], 'Quem tem o cão e qual a cor da casa dela?', array['Nina, casa branca', 'Mel, casa azul', 'Nina, casa azul', 'Lia, casa branca', 'Lia, casa verde']::text[], 0, 'Mel tem peixe, então não mora na verde (lá mora quem tem gato) e também não mora na branca: mora na azul. Nina não mora na verde, então mora na branca, e Lia fica com a verde e o gato. Sobra o cão para Nina, na casa branca.', 3),
  ('assoc-03', 'associacaoLogica', 'Quatro amigos — Paulo, Rui, Sara e Tito — disputaram uma corrida, sem empates.', array['Paulo chegou antes de Rui.', 'Sara chegou imediatamente depois de Paulo.', 'Tito não foi nem o primeiro nem o último.']::text[], 'Quem chegou em último lugar?', array['Rui', 'Tito', 'Não é possível determinar', 'Paulo', 'Sara']::text[], 0, 'Tito ficou em 2º ou 3º. Sara vem logo depois de Paulo, e Paulo antes de Rui. A única ordem possível é Paulo, Sara, Tito, Rui.', 2),
  ('assoc-04', 'associacaoLogica', 'Dani, Edu, Fê e Gil vão ao dentista em dias diferentes, de segunda a quinta.', array['Fê vai na quinta.', 'Dani vai no dia seguinte ao de Gil.', 'Edu não vai na segunda.', 'Gil não vai na terça.']::text[], 'Em que dia vai Edu?', array['Quinta', 'Segunda', 'Não é possível determinar', 'Terça', 'Quarta']::text[], 4, 'Fê vai na quinta, então Gil e Dani ocupam dois dias seguidos entre segunda e quarta. Gil não vai na terça, então Gil vai na segunda e Dani na terça. Sobra a quarta para Edu (que, de fato, não vai na segunda).', 2),
  ('frac-01', 'fracoes', 'João gastou 1/3 do salário com aluguel e 1/4 com mercado.', null::text[], 'Que fração do salário sobrou?', array['2/7', '1/2', '7/12', '1/12', '5/12']::text[], 4, '1/3 + 1/4 = 4/12 + 3/12 = 7/12 gastos. Sobram 12/12 − 7/12 = 5/12.', 1),
  ('frac-02', 'fracoes', 'Em uma caixa, 2/5 das bolas são azuis, e há 18 bolas azuis.', null::text[], 'Quantas bolas há na caixa?', array['45', '36', '30', '40', '54']::text[], 0, 'Se 2/5 são 18, então 1/5 é 9, e o total (5/5) é 45.', 1),
  ('frac-03', 'fracoes', 'Maria leu 3/8 de um livro no primeiro dia e metade do que faltava no segundo dia.', null::text[], 'Que fração do livro ainda falta ler?', array['1/4', '5/8', '5/16', '3/16', '1/8']::text[], 2, 'Depois do 1º dia faltavam 5/8. Ela leu metade disso (5/16), então ainda faltam 5/16.', 2),
  ('frac-04', 'fracoes', 'Uma torneira enche um tanque em 6 horas, e outra enche o mesmo tanque em 3 horas.', null::text[], 'Abertas juntas, em quanto tempo enchem o tanque?', array['4,5 horas', '1,5 hora', '2,5 horas', '2 horas', '3 horas']::text[], 3, 'Por hora, a primeira enche 1/6 e a segunda 1/3 = 2/6. Juntas: 3/6 = 1/2 do tanque por hora, então 2 horas.', 2),
  ('frac-05', 'fracoes', 'Em uma herança, Ana recebeu metade. Bruno recebeu 1/3 do que sobrou, e Carla ficou com o restante, R$ 20.000.', null::text[], 'Qual era o valor total da herança?', array['R$ 50.000', 'R$ 60.000', 'R$ 80.000', 'R$ 120.000', 'R$ 40.000']::text[], 1, 'Depois de Ana sobra 1/2. Bruno leva 1/3 disso (1/6). Carla fica com 1/2 − 1/6 = 1/3 do total. Se 1/3 é R$ 20.000, o total é R$ 60.000.', 3),
  ('frac-06', 'fracoes', 'Considere as frações 3/4, 5/7, 7/9, 2/3 e 11/15.', null::text[], 'Qual é a maior?', array['3/4', '5/7', '7/9', '11/15', '2/3']::text[], 2, 'Em decimal: 3/4 = 0,75; 5/7 ≈ 0,714; 7/9 ≈ 0,778; 2/3 ≈ 0,667; 11/15 ≈ 0,733. A maior é 7/9.', 2),
  ('pct-01', 'porcentagem', 'Um produto custava R$ 200. O preço subiu 10% e, depois, caiu 10%.', null::text[], 'Qual é o preço final?', array['R$ 180', 'R$ 202', 'R$ 200', 'R$ 198', 'R$ 196']::text[], 3, '200 × 1,1 = 220. Depois, 220 × 0,9 = 198. Os 10% de queda incidem sobre um valor maior.', 1),
  ('pct-02', 'porcentagem', 'Uma loja dá um desconto de 20% e, sobre o novo preço, mais 10%.', null::text[], 'Qual é o desconto total equivalente?', array['25%', '30%', '28%', '27%', '32%']::text[], 2, 'Sobra 0,8 × 0,9 = 0,72 do preço. Logo, o desconto total é 28%, e não 30%.', 2),
  ('pct-03', 'porcentagem', 'Um salário passou de R$ 2.500 para R$ 2.800.', null::text[], 'De quantos por cento foi o aumento?', array['300%', '15%', '10%', '12%', '11%']::text[], 3, 'O aumento foi de R$ 300. 300 ÷ 2.500 = 0,12 = 12%.', 1),
  ('pct-04', 'porcentagem', 'Após um desconto de 25%, um produto passou a custar R$ 150.', null::text[], 'Qual era o preço original?', array['R$ 180', 'R$ 200', 'R$ 187,50', 'R$ 225', 'R$ 175']::text[], 1, 'R$ 150 corresponde a 75% do preço. 150 ÷ 0,75 = R$ 200. (Somar 25% de 150 daria R$ 187,50, que está errado.)', 2),
  ('pct-05', 'porcentagem', 'Uma turma tem 40 alunos, e 35% são meninos.', null::text[], 'Quantas são as meninas?', array['28', '24', '14', '26', '25']::text[], 3, 'Meninos: 35% de 40 = 14. Meninas: 40 − 14 = 26.', 1),
  ('pct-06', 'porcentagem', 'A população de uma cidade cresceu 20% em um ano e mais 20% no ano seguinte.', null::text[], 'Qual foi o crescimento total nos dois anos?', array['24%', '42%', '44%', '48%', '40%']::text[], 2, '1,2 × 1,2 = 1,44. O crescimento total foi de 44%.', 2),
  ('pct-07', 'porcentagem', 'Calcule 30% de 40% de 500.', null::text[], 'Qual é o resultado?', array['60', '150', '120', '70', '35']::text[], 0, '40% de 500 = 200. 30% de 200 = 60.', 1),
  ('prob-01', 'probabilidade', 'Um dado comum, de 6 faces, é lançado uma vez.', null::text[], 'Qual a probabilidade de sair um número primo?', array['1/2', '5/6', '1/6', '2/3', '1/3']::text[], 0, 'Os primos de 1 a 6 são 2, 3 e 5: 3 casos em 6, ou seja, 1/2.', 1),
  ('prob-02', 'probabilidade', 'Dois dados comuns são lançados.', null::text[], 'Qual a probabilidade de a soma ser 7?', array['1/12', '1/4', '7/36', '1/6', '1/9']::text[], 3, 'Há 36 resultados possíveis e 6 dão soma 7: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1). 6/36 = 1/6.', 1),
  ('prob-03', 'probabilidade', 'Uma urna tem 3 bolas vermelhas e 2 azuis. Retiram-se 2 bolas, uma depois da outra, sem devolver.', null::text[], 'Qual a probabilidade de as duas serem vermelhas?', array['3/5', '3/10', '1/2', '9/25', '2/5']::text[], 1, 'Primeira vermelha: 3/5. Sobram 2 vermelhas em 4 bolas: 2/4. Multiplicando: 3/5 × 1/2 = 3/10.', 2),
  ('prob-04', 'probabilidade', 'Uma moeda honesta é lançada 3 vezes.', null::text[], 'Qual a probabilidade de sair pelo menos uma cara?', array['7/8', '3/8', '3/4', '5/8', '1/2']::text[], 0, 'É mais fácil calcular o contrário: nenhuma cara (coroa, coroa, coroa) tem chance 1/8. Logo, 1 − 1/8 = 7/8.', 2),
  ('prob-05', 'probabilidade', 'Sorteia-se um número inteiro de 1 a 30.', null::text[], 'Qual a probabilidade de ele ser múltiplo de 3 ou de 5?', array['7/15', '8/15', '1/2', '1/3', '2/5']::text[], 0, 'Múltiplos de 3: 10. Múltiplos de 5: 6. Os múltiplos de 15 (15 e 30) foram contados duas vezes. 10 + 6 − 2 = 14, e 14/30 = 7/15.', 3),
  ('prob-06', 'probabilidade', 'Em uma turma, 60% das pessoas são mulheres. Usam óculos 25% das mulheres e 50% dos homens.', null::text[], 'Sorteando uma pessoa da turma, qual a probabilidade de ela usar óculos?', array['75%', '35%', '37,5%', '30%', '40%']::text[], 1, 'Mulheres de óculos: 60% × 25% = 15%. Homens de óculos: 40% × 50% = 20%. Total: 15% + 20% = 35%.', 3),
  ('prob-07', 'probabilidade', 'Dois dados comuns são lançados.', null::text[], 'Qual a probabilidade de o produto dos resultados ser par?', array['1/4', '3/4', '2/3', '1/2', '5/6']::text[], 1, 'O produto só é ímpar se os dois forem ímpares: 1/2 × 1/2 = 1/4. Logo, par = 1 − 1/4 = 3/4.', 2),
  ('prop-01', 'proposicoes', 'Considere a proposição: “Se estudo, então passo.”', null::text[], 'Qual proposição é equivalente a ela?', array['Estudo e não passo.', 'Estudo ou passo.', 'Se passo, então estudo.', 'Se não passo, então não estudo.', 'Se não estudo, então não passo.']::text[], 3, 'A condicional p → q equivale à contrapositiva ¬q → ¬p. Inverter (q → p) ou só negar (¬p → ¬q) não preserva o sentido.', 2),
  ('prop-02', 'proposicoes', 'Considere a proposição: “Se chove, então levo guarda-chuva.”', null::text[], 'Qual é a negação dela?', array['Não chove e levo guarda-chuva.', 'Não chove ou não levo guarda-chuva.', 'Chove e não levo guarda-chuva.', 'Se não chove, então não levo guarda-chuva.', 'Se chove, então não levo guarda-chuva.']::text[], 2, 'A condicional só é falsa quando a primeira parte acontece e a segunda não. Por isso, ¬(p → q) é p ∧ ¬q.', 2),
  ('prop-03', 'proposicoes', 'Considere a proposição: “Hoje chove e faz frio.”', null::text[], 'Qual é a negação dela?', array['Hoje chove ou faz frio.', 'Hoje não chove ou não faz frio.', 'Hoje chove e não faz frio.', 'Se hoje chove, então não faz frio.', 'Hoje não chove e não faz frio.']::text[], 1, 'Pela lei de De Morgan, ¬(p ∧ q) = ¬p ∨ ¬q: basta uma das partes falhar.', 1),
  ('prop-04', 'proposicoes', 'Considere a proposição: “Todo aluno estuda.”', null::text[], 'Qual é a negação dela?', array['Nenhum aluno estuda.', 'Algum aluno não estuda.', 'Algum aluno estuda.', 'Nenhum aluno não estuda.', 'Todo aluno não estuda.']::text[], 1, 'Para desmentir “todo aluno estuda”, basta um aluno que não estude. A negação de “todo” é “algum… não”.', 1),
  ('prop-05', 'proposicoes', 'Considere a proposição: “Nenhum gato é preto.”', null::text[], 'Qual é a negação dela?', array['Algum gato não é preto.', 'Algum gato é preto.', 'Todo gato é preto.', 'Nenhum gato é branco.', 'Todo gato não é preto.']::text[], 1, 'Para desmentir “nenhum gato é preto”, basta existir um gato preto. A negação de “nenhum” é “algum”.', 1),
  ('prop-06', 'proposicoes', 'Sabe-se que p é verdadeira, q é falsa e r é verdadeira.', null::text[], 'Qual é o valor lógico de (p → q) ∨ ¬r?', array['Depende de q', 'Não é possível determinar', 'Verdadeiro', 'Depende de p', 'Falso']::text[], 4, 'p → q é V → F, que é falso. ¬r é falso. Falso ∨ falso = falso.', 2),
  ('prop-07', 'proposicoes', 'Uma tautologia é uma proposição sempre verdadeira, qualquer que seja o valor de suas partes.', null::text[], 'Qual das opções é uma tautologia?', array['p ↔ q', '(p ∧ q) → p', 'p → q', 'p ∨ q', 'p ∧ ¬p']::text[], 1, 'Se p ∧ q é verdadeira, p é verdadeira; se p ∧ q é falsa, a condicional já é verdadeira. Em todos os casos dá verdadeiro.', 3),
  ('prop-08', 'proposicoes', 'Considere a condicional p → q.', null::text[], 'Em qual situação ela é FALSA?', array['Ela nunca é falsa', 'p falsa e q verdadeira', 'p e q falsas', 'p e q verdadeiras', 'p verdadeira e q falsa']::text[], 4, 'A condicional promete que, se p acontecer, q acontece. Ela só é quebrada quando p acontece e q não.', 1),
  ('fig-01', 'sequenciasFiguras', 'Observe a sequência: ▲ ■ ● ▲ ■ ● ▲ ?', null::text[], 'Qual figura completa a sequência?', array['▲', '■', '●', '◆', '★']::text[], 1, 'As figuras se repetem em grupos de três: ▲ ■ ●. A 8ª é a 2ª do grupo: ■.', 1),
  ('fig-02', 'sequenciasFiguras', 'A seta gira sempre da mesma forma: ↑ → ↓ ← ↑ ?', null::text[], 'Qual é a próxima posição?', array['↗', '↑', '↓', '←', '→']::text[], 4, 'A seta gira 90° no sentido horário a cada passo. Depois de ↑ vem →.', 1),
  ('fig-03', 'sequenciasFiguras', 'Observe: ↑ ↗ → ↘ ↓ ?', null::text[], 'Qual é a próxima seta?', array['←', '↙', '↓', '↘', '↖']::text[], 1, 'A seta gira 45° no sentido horário a cada passo. Depois de ↓ vem ↙.', 2),
  ('fig-04', 'sequenciasFiguras', 'Observe: ★  |  ★★★  |  ★★★★★  |  ?', null::text[], 'Quantas estrelas tem a próxima figura?', array['8', '6', '7', '5', '9']::text[], 2, 'A quantidade cresce de 2 em 2: 1, 3, 5… a próxima tem 7.', 1),
  ('fig-05', 'sequenciasFiguras', 'Observe: ▲ □ ● △ ■ ○ ?', null::text[], 'Qual figura vem a seguir?', array['△', '□', '▲', '○', '■']::text[], 2, 'Duas regras ao mesmo tempo: a forma segue triângulo, quadrado, círculo, e o preenchimento alterna cheio, vazio. A 7ª é um triângulo, na posição ímpar: cheio (▲).', 3),
  ('fig-06', 'sequenciasFiguras', 'Observe os pares: [↑ ↓]  [→ ←]  [↓ ↑]  [? ?]', null::text[], 'Qual par vem a seguir?', array['← ↑', '↑ ↓', '← →', '→ ←', '↓ ↑']::text[], 2, 'Em cada par a segunda seta aponta para o lado oposto da primeira, e a primeira seta gira 90° no sentido horário de um par para o outro: ↑, →, ↓, ←.', 3),
  ('let-01', 'sequenciasLetras', 'Considere o alfabeto de 26 letras (com K, W e Y). Observe: A, C, F, J, O, …', null::text[], 'Qual é a próxima?', array['Q', 'T', 'S', 'U', 'V']::text[], 3, 'Os saltos crescem: +2, +3, +4, +5, então +6. O (15ª) + 6 = U (21ª).', 2),
  ('let-02', 'sequenciasLetras', 'Considere o alfabeto de 26 letras (com K, W e Y). Observe: A, B, D, G, K, …', null::text[], 'Qual é a próxima?', array['O', 'N', 'Q', 'R', 'P']::text[], 4, 'Saltos de +1, +2, +3, +4, então +5. K (11ª) + 5 = P (16ª).', 1),
  ('let-03', 'sequenciasLetras', 'Considere o alfabeto de 26 letras (com K, W e Y). Observe: Z, X, U, Q, L, …', null::text[], 'Qual é a próxima?', array['G', 'D', 'F', 'H', 'E']::text[], 2, 'Andando para trás: −2, −3, −4, −5, então −6. L (12ª) − 6 = F (6ª).', 2),
  ('let-04', 'sequenciasLetras', 'Considere o alfabeto de 26 letras (com K, W e Y). Observe: AZ, BY, CX, DW, …', null::text[], 'Qual é a próxima?', array['FV', 'EV', 'EU', 'EW', 'DV']::text[], 1, 'A primeira letra avança no alfabeto (A, B, C, D, E) e a segunda recua a partir do fim (Z, Y, X, W, V).', 1),
  ('let-05', 'sequenciasLetras', 'Considere o alfabeto de 26 letras (com K, W e Y). Observe: ACE, BDF, CEG, …', null::text[], 'Qual é a próxima?', array['DEF', 'DFH', 'CFH', 'DFG', 'EGI']::text[], 1, 'Cada grupo pula uma letra (A_C_E) e o grupo seguinte começa uma letra adiante: ACE, BDF, CEG, DFH.', 1),
  ('let-06', 'sequenciasLetras', 'Considere o alfabeto de 26 letras (com K, W e Y). Observe: A1, C3, E5, G7, …', null::text[], 'Qual é a próxima?', array['H8', 'I10', 'I9', 'I8', 'J9']::text[], 2, 'As letras pulam de 2 em 2 (A, C, E, G, I) e o número acompanha a posição da letra no alfabeto: I é a 9ª.', 1),
  ('let-07', 'sequenciasLetras', 'Considere o alfabeto de 26 letras (com K, W e Y). Observe: B, E, J, Q, …', null::text[], 'Qual é a próxima?', array['W', 'Z', 'Y', 'U', 'X']::text[], 1, 'As posições são 2, 5, 10, 17: quadrados mais 1 (1²+1, 2²+1, 3²+1, 4²+1). A próxima é 5²+1 = 26: Z.', 3),
  ('num-01', 'sequenciasNumericas', 'Observe a sequência: 3, 7, 15, 31, 63, …', null::text[], 'Qual é o próximo termo?', array['128', '125', '127', '131', '126']::text[], 2, 'Cada termo é o dobro do anterior mais 1: 63 × 2 + 1 = 127.', 1),
  ('num-02', 'sequenciasNumericas', 'Observe a sequência: 2, 3, 5, 9, 17, …', null::text[], 'Qual é o próximo termo?', array['31', '25', '33', '34', '35']::text[], 2, 'As diferenças dobram: +1, +2, +4, +8, então a próxima é +16: 17 + 16 = 33.', 2),
  ('num-03', 'sequenciasNumericas', 'Observe a sequência: 2, 5, 10, 17, 26, …', null::text[], 'Qual é o próximo termo?', array['37', '38', '35', '36', '41']::text[], 0, 'Cada termo é um quadrado perfeito mais 1: 1²+1, 2²+1, …, 6²+1 = 37.', 1),
  ('num-04', 'sequenciasNumericas', 'Observe a sequência: 5, 10, 8, 16, 14, 28, …', null::text[], 'Qual é o próximo termo?', array['32', '56', '30', '24', '26']::text[], 4, 'As operações se alternam: ×2, −2, ×2, −2… Depois de 28 vem 28 − 2 = 26.', 2),
  ('num-05', 'sequenciasNumericas', 'Observe a sequência: 1, 20, 3, 17, 5, 14, 7, …', null::text[], 'Qual é o próximo termo?', array['13', '11', '9', '12', '10']::text[], 1, 'São duas sequências intercaladas: 1, 3, 5, 7 (+2) e 20, 17, 14 (−3). O próximo é da segunda: 14 − 3 = 11.', 2),
  ('num-06', 'sequenciasNumericas', 'Observe a sequência: 1, 3, 4, 7, 11, 18, …', null::text[], 'Qual é o próximo termo?', array['36', '27', '25', '28', '29']::text[], 4, 'Cada termo é a soma dos dois anteriores: 11 + 18 = 29.', 1),
  ('num-07', 'sequenciasNumericas', 'Observe a sequência: 6, 11, 21, 36, 56, …', null::text[], 'Qual é o próximo termo?', array['81', '76', '80', '77', '86']::text[], 0, 'As diferenças crescem de 5 em 5: +5, +10, +15, +20, então +25: 56 + 25 = 81.', 2),
  ('num-08', 'sequenciasNumericas', 'Observe a sequência: 2, 6, 24, 120, …', null::text[], 'Qual é o próximo termo?', array['240', '480', '720', '840', '600']::text[], 2, 'Multiplica-se por 3, por 4, por 5… O próximo é 120 × 6 = 720.', 2),
  ('num-09', 'sequenciasNumericas', 'Observe a sequência: 4, 6, 9, 13,5, …', null::text[], 'Qual é o próximo termo?', array['19,5', '22,5', '20,25', '18', '20']::text[], 2, 'Cada termo é o anterior multiplicado por 1,5: 13,5 × 1,5 = 20,25.', 3),
  ('pal-01', 'sequenciasPalavras', 'Observe: SOL, CASA, JANELA, BORBOLETA, …', null::text[], 'Qual palavra continua a sequência?', array['ELEFANTE', 'CADERNO', 'TELEFONE', 'MATEMÁTICA', 'BICICLETA']::text[], 3, 'O número de vogais cresce de 1 em 1: SOL (1), CASA (2), JANELA (3), BORBOLETA (4). MATEMÁTICA tem 5.', 2),
  ('pal-02', 'sequenciasPalavras', 'Observe: CASA → AMOR → RATO → ORELHA → …', null::text[], 'Qual palavra continua a sequência?', array['MALA', 'LUA', 'RIO', 'ABACAXI', 'BOLA']::text[], 3, 'Cada palavra começa com a última letra da anterior. ORELHA termina em A, e a única opção que começa com A é ABACAXI.', 1),
  ('pal-03', 'sequenciasPalavras', 'Observe: ABELHA, CAVALO, ELEFANTE, GATO, …', null::text[], 'Qual palavra continua a sequência?', array['IGUANA', 'LEÃO', 'JACARÉ', 'FOCA', 'HIENA']::text[], 0, 'As iniciais pulam uma letra: A, C, E, G… a próxima é I.', 1),
  ('pal-04', 'sequenciasPalavras', 'Considere a palavra AMOR.', null::text[], 'Qual das palavras abaixo NÃO é um anagrama de AMOR?', array['OMAR', 'ROMA', 'RAMO', 'MURO', 'MORA']::text[], 3, 'Anagramas usam exatamente as mesmas letras. MURO tem U e não tem A.', 1),
  ('pal-05', 'sequenciasPalavras', 'Pé está para meia assim como mão está para…', null::text[], 'Qual palavra completa a analogia?', array['dedo', 'unha', 'luva', 'braço', 'anel']::text[], 2, 'A meia é o que se veste no pé; a luva é o que se veste na mão.', 1),
  ('pal-06', 'sequenciasPalavras', 'Livro está para biblioteca assim como quadro está para…', null::text[], 'Qual palavra completa a analogia?', array['museu', 'tinta', 'moldura', 'pintor', 'parede']::text[], 0, 'A biblioteca é o lugar onde se reúnem e expõem livros; o museu é o lugar onde se reúnem e expõem quadros.', 2),
  ('pal-07', 'sequenciasPalavras', 'As palavras ARARA, OVO, RADAR e SALAS têm algo em comum.', null::text[], 'Qual palavra também tem essa característica?', array['AMORA', 'RIVAL', 'MELÃO', 'SOPAS', 'REVIVER']::text[], 4, 'Todas são palíndromos: leem-se igual de trás para frente. REVIVER também é.', 2),
  ('vm-01', 'verdadeMentira', 'Um vaso foi quebrado por uma de três crianças. Apenas uma delas diz a verdade.', array['Ana: “Foi o Beto.”', 'Beto: “Não fui eu.”', 'Caio: “Não fui eu.”']::text[], 'Quem quebrou o vaso?', array['Não é possível saber', 'Ana ou Beto', 'Caio', 'Beto', 'Ana']::text[], 2, 'Teste cada hipótese. Se foi Ana ou Beto, duas frases seriam verdadeiras. Se foi Caio, só a de Beto é verdadeira. Logo, foi Caio.', 1),
  ('vm-02', 'verdadeMentira', 'Em uma ilha, cavaleiros sempre dizem a verdade e valetes sempre mentem. A diz: “Pelo menos um de nós dois é valete.”', null::text[], 'O que são A e B?', array['A é cavaleiro e B é valete', 'Os dois são cavaleiros', 'Os dois são valetes', 'Não é possível saber', 'A é valete e B é cavaleiro']::text[], 0, 'Se A fosse valete, a frase seria verdadeira (ele mesmo é valete), e valete não diz verdade. Então A é cavaleiro, a frase é verdadeira e B é valete.', 2),
  ('vm-03', 'verdadeMentira', 'Cada pessoa abaixo sempre diz a verdade ou sempre mente.', array['Alex: “Bia mente.”', 'Bia: “Caio mente.”', 'Caio: “Alex e Bia mentem.”']::text[], 'Quem diz a verdade?', array['Apenas Alex', 'Alex e Caio', 'Apenas Caio', 'Apenas Bia', 'Ninguém']::text[], 3, 'Se Caio dissesse a verdade, Alex e Bia mentiriam; mas Alex mentindo significa que Bia diz a verdade, contradição. Logo Caio mente, então Bia diz a verdade (Caio mente) e Alex mente (Bia não mente).', 3),
  ('vm-04', 'verdadeMentira', 'Um dos quatro amigos comeu o último pedaço de bolo. Exatamente um deles mente.', array['Lucas: “Foi o Marcos.”', 'Marcos: “Não foi o Lucas.”', 'Nara: “Foi o Otávio ou o Marcos.”', 'Otávio: “Não foi a Nara.”']::text[], 'Quem comeu o bolo?', array['Não é possível saber', 'Otávio', 'Nara', 'Lucas', 'Marcos']::text[], 1, 'Se foi Marcos, ninguém mentiria. Se foi Lucas ou Nara, três mentiriam. Só com Otávio há exatamente uma mentira (a de Lucas).', 3),
  ('vm-05', 'verdadeMentira', 'Um de três irmãos esqueceu a porta aberta. Só um deles fala a verdade.', array['André: “Não fui eu.”', 'Bruno: “Não fui eu.”', 'Cecília: “Foi o André.”']::text[], 'Quem esqueceu a porta aberta?', array['Bruno', 'André ou Cecília', 'André', 'Não é possível saber', 'Cecília']::text[], 0, 'Se foi André, Bruno e Cecília diriam a verdade (duas verdades). Se foi Cecília, André e Bruno diriam a verdade (duas). Se foi Bruno, só André diz a verdade. Logo, foi Bruno.', 2)
) as v (id, topic_slug, statement, premises, prompt, options, correct_index, explanation, difficulty),
  public.topics as t
where t.slug = v.topic_slug
on conflict (id) do update set
  topic_id = excluded.topic_id,
  statement = excluded.statement,
  premises = excluded.premises,
  prompt = excluded.prompt,
  options = excluded.options,
  correct_index = excluded.correct_index,
  explanation = excluded.explanation,
  difficulty = excluded.difficulty,
  active = true;

-- Questões que saíram dos arquivos não podem ser apagadas (as respostas apontam para elas): ficam inativas.
update public.questions set active = false
where active and id not in ('arg-01', 'arg-02', 'arg-03', 'arg-04', 'arg-05', 'arg-06', 'assoc-01', 'assoc-02', 'assoc-03', 'assoc-04', 'frac-01', 'frac-02', 'frac-03', 'frac-04', 'frac-05', 'frac-06', 'pct-01', 'pct-02', 'pct-03', 'pct-04', 'pct-05', 'pct-06', 'pct-07', 'prob-01', 'prob-02', 'prob-03', 'prob-04', 'prob-05', 'prob-06', 'prob-07', 'prop-01', 'prop-02', 'prop-03', 'prop-04', 'prop-05', 'prop-06', 'prop-07', 'prop-08', 'fig-01', 'fig-02', 'fig-03', 'fig-04', 'fig-05', 'fig-06', 'let-01', 'let-02', 'let-03', 'let-04', 'let-05', 'let-06', 'let-07', 'num-01', 'num-02', 'num-03', 'num-04', 'num-05', 'num-06', 'num-07', 'num-08', 'num-09', 'pal-01', 'pal-02', 'pal-03', 'pal-04', 'pal-05', 'pal-06', 'pal-07', 'vm-01', 'vm-02', 'vm-03', 'vm-04', 'vm-05');
